create table public.institutional_page_profiles (
  content_id uuid primary key references public.content_items(id) on delete cascade,
  page_kind text not null check (page_kind in ('about', 'editorial-policy', 'authors', 'contact', 'legal', 'privacy', 'commercial-disclosure')),
  eyebrow text not null default '',
  sections jsonb not null default '[]'::jsonb check (jsonb_typeof(sections) = 'array'),
  notice text not null default '',
  contact_email text,
  last_reviewed_on date,
  requires_legal_review boolean not null default false,
  updated_at timestamptz not null default now()
);

create index institutional_page_profiles_kind_index on public.institutional_page_profiles (page_kind, last_reviewed_on desc);
alter table public.institutional_page_profiles enable row level security;

create policy "Published institutional profiles are readable" on public.institutional_page_profiles
  for select to anon, authenticated
  using (exists (select 1 from public.content_items c where c.id = institutional_page_profiles.content_id and c.content_type = 'page' and c.status = 'published'));
create policy "Admins manage institutional profiles" on public.institutional_page_profiles
  for all to authenticated
  using (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'))
  with check (exists (select 1 from public.profiles p where p.id = auth.uid() and p.role = 'admin'));

revoke all on table public.institutional_page_profiles from anon, authenticated;
grant select on public.institutional_page_profiles to anon;
grant select, insert, update, delete on public.institutional_page_profiles to authenticated;

insert into public.content_items (content_type, status, title, slug, excerpt, body, seo_title, seo_description, published_at) values
('page', 'published', 'About Natura', 'about', 'Learn why Natura publishes practical, source-aware gardening guidance for balconies, patios, containers, and indoor growing spaces.',
 '{"overview":"Natura is an independent gardening publication built for people who grow in real, limited spaces. Our aim is to turn reliable horticultural information into clear decisions without pretending that one climate, container, or routine works everywhere.","navigation":{"section":"institutional","subsection":"about"},"sources":[],"seo_keyword_strategy":{"focus_keyword":"about Natura gardening","supporting_keywords":["Natura editorial mission","small space gardening guidance"],"search_intent":"navigational"}}',
 'About Natura Gardening', 'Meet Natura, an independent gardening publication focused on practical, source-aware advice for balconies, patios, containers, and indoor spaces.', now()),
('page', 'published', 'Editorial policy', 'editorial-policy', 'See how Natura chooses topics, checks sources, distinguishes observation from evidence, corrects errors, and reviews published gardening guidance.',
 '{"overview":"Our editorial process starts with a real reader question, identifies the limits that could change the answer, and then uses relevant primary or expert sources. We write original explanations, label uncertainty, and revise content when better evidence or material corrections become available.","navigation":{"section":"institutional","subsection":"editorial-policy"},"sources":[],"seo_keyword_strategy":{"focus_keyword":"Natura editorial policy","supporting_keywords":["gardening content standards","Natura corrections policy"],"search_intent":"navigational"}}',
 'Natura Editorial Policy', 'Read Natura’s standards for research, sources, corrections, practical testing, uncertainty, AI assistance, and the review of published gardening guidance.', now()),
('page', 'published', 'Authors and reviewers', 'authors', 'Understand who prepares Natura content, how expertise is represented, and how authorship and review records will develop before public launch.',
 '{"overview":"Natura treats authorship as an accountability record, not a decorative byline. Every public article should eventually identify the person responsible for the writing and, where appropriate, the subject reviewer who checked specialised claims.","navigation":{"section":"institutional","subsection":"authors"},"sources":[],"seo_keyword_strategy":{"focus_keyword":"Natura authors and reviewers","supporting_keywords":["Natura editorial team","gardening content reviewers"],"search_intent":"navigational"}}',
 'Natura Authors and Reviewers', 'Learn how Natura records authorship, editorial responsibility, subject review, contributor biographies, conflicts of interest, and article updates.', now()),
('page', 'published', 'Contact Natura', 'contact', 'Contact Natura about an editorial correction, source, privacy request, partnership disclosure, accessibility issue, or general website feedback.',
 '{"overview":"Useful feedback helps Natura improve. When writing, include the page URL and a concise description of the issue. Do not send sensitive personal information, medical details, account credentials, or confidential commercial material.","navigation":{"section":"institutional","subsection":"contact"},"sources":[],"seo_keyword_strategy":{"focus_keyword":"contact Natura","supporting_keywords":["Natura editorial correction","Natura privacy contact"],"search_intent":"navigational"}}',
 'Contact Natura', 'Contact Natura for editorial corrections, source questions, privacy requests, accessibility issues, partnership disclosures, or general feedback.', now()),
('page', 'published', 'Legal notice and terms of use', 'legal-notice', 'Read the pre-launch terms governing Natura’s informational gardening content, external links, intellectual property, availability, and responsible use.',
 '{"overview":"Natura provides general educational information, not a guarantee of plant performance or a substitute for local professional advice. Growing outcomes depend on climate, weather, plant health, materials, building rules, and the decisions made by each reader.","navigation":{"section":"institutional","subsection":"legal"},"sources":[],"seo_keyword_strategy":{"focus_keyword":"Natura legal notice","supporting_keywords":["Natura terms of use","gardening website disclaimer"],"search_intent":"navigational"}}',
 'Natura Legal Notice and Terms', 'Read Natura’s pre-launch terms covering informational gardening content, external links, intellectual property, availability, and responsible use.', now()),
('page', 'published', 'Privacy policy', 'privacy-policy', 'Understand Natura’s current local-development data practices and the items that must be confirmed before analytics, forms, hosting, or advertising are activated.',
 '{"overview":"The current Natura build runs locally. It does not intentionally operate public analytics, advertising, newsletter, or contact-form services. This notice must be reviewed and expanded before deployment to reflect the real operator, hosting, logs, cookies, processors, retention periods, legal bases, and user rights.","navigation":{"section":"institutional","subsection":"privacy"},"sources":[{"title":"ICO — The right to be informed","url":"https://ico.org.uk/for-organisations/uk-gdpr-guidance-and-resources/individual-rights/the-right-to-be-informed/"}],"seo_keyword_strategy":{"focus_keyword":"Natura privacy policy","supporting_keywords":["Natura personal data","Natura cookies"],"search_intent":"navigational"}}',
 'Natura Privacy Policy', 'Read Natura’s local-development privacy notice and the disclosures that must be completed before hosting, analytics, forms, advertising, or cookies are enabled.', now()),
('page', 'published', 'Commercial disclosure', 'commercial-disclosure', 'Learn how Natura identifies affiliate links, supplied products, sponsorships, advertising, and other relationships that could influence a recommendation.',
 '{"overview":"Readers should be able to understand the evidence behind a recommendation and any commercial relationship that could affect how they evaluate it. Natura places a specific disclosure near relevant comparisons and maintains this broader policy as a reference.","navigation":{"section":"institutional","subsection":"commercial-disclosure"},"sources":[{"title":"FTC — Advertisement endorsements","url":"https://www.ftc.gov/news-events/topics/truth-advertising/advertisement-endorsements"}],"seo_keyword_strategy":{"focus_keyword":"Natura commercial disclosure","supporting_keywords":["Natura affiliate disclosure","Natura sponsored content policy"],"search_intent":"navigational"}}',
 'Natura Commercial Disclosure', 'Learn how Natura labels affiliate links, product samples, sponsorships, advertising, review independence, and other material commercial relationships.', now())
on conflict (slug) do nothing;

insert into public.institutional_page_profiles (content_id, page_kind, eyebrow, sections, notice, contact_email, last_reviewed_on, requires_legal_review)
select content.id, profile.page_kind, profile.eyebrow, profile.sections::jsonb, profile.notice, profile.contact_email, current_date, profile.requires_legal_review
from public.content_items content join (values
  ('about', 'about', 'Independent by design', '[{"heading":"Our mission","body":"We help people make better growing decisions in small spaces through practical explanations, visible limits, and clear next steps."},{"heading":"Who Natura serves","body":"Natura is designed for balcony, patio, container, and indoor gardeners who need advice that respects light, wind, drainage, climate, available time, and rented spaces."},{"heading":"What independence means","body":"Editorial conclusions are separated from advertising and commercial relationships. When a relationship exists, it must be stated where the reader encounters the recommendation."}]', '', null, false),
  ('editorial-policy', 'editorial-policy', 'How we work', '[{"heading":"Research and sources","body":"We prefer primary research, official guidance, university extension material, standards, and clearly identified expert sources. Sources are selected for relevance, not to decorate an article."},{"heading":"Writing and verification","body":"The writer distinguishes documented evidence, practical inference, and hands-on observation. Important limits, climate differences, and safety considerations remain visible in the finished article."},{"heading":"Corrections and updates","body":"Material corrections should be made promptly and recorded through the editorial revision history. Dates and claims are reviewed when a page is updated."},{"heading":"Use of AI tools","body":"AI may support planning, drafting, coding, or quality checks, but it does not replace source verification, editorial responsibility, or human publication decisions."}]', '', null, false),
  ('authors', 'authors', 'Accountable expertise', '[{"heading":"Current pre-launch team","body":"Natura is currently being developed through a protected editorial workflow. Named contributor profiles, roles, credentials, and contact channels must be completed before the public launch."},{"heading":"Author records","body":"A future author profile will state the contributor’s role, relevant experience, areas of coverage, conflicts of interest, and the pages for which they are responsible."},{"heading":"Subject review","body":"Higher-risk or specialised claims should identify an appropriate reviewer. A review label must describe what was checked rather than imply approval that did not occur."}]', 'Contributor identities and biographies are not yet final. This page is visible locally so the workflow can be tested, but it must be completed before public launch.', null, true),
  ('contact', 'contact', 'Corrections and questions', '[{"heading":"Editorial corrections","body":"Send the page URL, the statement you believe is inaccurate, and a reliable supporting source. Natura will review the evidence and record material updates in the editorial workflow."},{"heading":"Privacy and accessibility","body":"Use the same address for privacy requests or accessibility barriers. Explain the desired outcome, but do not include unnecessary sensitive information."},{"heading":"Commercial enquiries","body":"Any proposed partnership, supplied product, sponsorship, or affiliate arrangement must be identified clearly so the editorial team can assess and disclose the relationship."}]', 'The address below is for local development only. Replace it with a monitored public address and confirm the responsible operator before deployment.', 'editorial@natura.local', true),
  ('legal-notice', 'legal', 'Pre-launch legal framework', '[{"heading":"Informational purpose","body":"Natura provides general educational gardening information. It does not guarantee results and does not replace local horticultural, structural, electrical, pesticide, medical, veterinary, or legal advice."},{"heading":"Reader responsibility","body":"Readers remain responsible for checking local rules, labels, building restrictions, allergies, toxicity, weather, and the suitability of any action for their circumstances."},{"heading":"External links and availability","body":"External links are provided for context and may change. Natura does not control third-party services and cannot promise continuous availability or error-free operation."},{"heading":"Content and reuse","body":"Original Natura text, design, and media may not be republished commercially without permission. Quotations and links should identify the source and respect applicable rights."}]', 'This is a functional pre-launch draft, not final legal advice. Operator identity, jurisdiction, governing law, address, and dispute terms require qualified review before publication on a public domain.', null, true),
  ('privacy-policy', 'privacy', 'Data transparency', '[{"heading":"Current local build","body":"The development site runs on a local computer with local Supabase services. It is not intended for public traffic, and public analytics, advertising, newsletter, and contact-form collection are not active."},{"heading":"Information that may exist locally","body":"Administrator account data, editorial content, revisions, media metadata, and technical logs may exist in the local development environment. Access is restricted to the authorised administrator workflow."},{"heading":"Before public deployment","body":"The final notice must name the operator and explain actual hosting logs, cookies, analytics, advertising, forms, processors, transfers, retention, legal bases, rights, and contact routes. Consent controls must match the technologies actually enabled."},{"heading":"Requests and updates","body":"A monitored privacy contact and applicable regulator information must be added after the operating jurisdiction is selected. This page should be reviewed whenever collection or processing changes."}]', 'Pre-launch privacy notice: it describes the current local build only and must not be treated as the final notice for a hosted service.', null, true),
  ('commercial-disclosure', 'commercial-disclosure', 'How relationships are disclosed', '[{"heading":"Editorial independence","body":"Commercial opportunity does not determine the editorial verdict. Comparisons use visible criteria, evidence levels, limitations, and a recorded publication decision."},{"heading":"Affiliate links","body":"If Natura may earn a commission from a link, that relationship should be stated clearly near the recommendation before the reader acts on it."},{"heading":"Products and sponsorships","body":"A supplied product, paid placement, sponsorship, or other material relationship must be identified in plain language. Sponsored content must not imitate independent editorial research."},{"heading":"No current monetisation","body":"The local development build does not currently use affiliate links, sponsored placements, or public advertising. This policy prepares the disclosure workflow for a later launch decision."}]', '', null, false)
) as profile(slug, page_kind, eyebrow, sections, notice, contact_email, requires_legal_review) on content.slug = profile.slug
where content.content_type = 'page'
on conflict (content_id) do nothing;
